import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';

export default function TeacherDashboard() {
  const { user, logout, API } = useAuth();
  const navigate = useNavigate();
  const [subject, setSubject] = useState('');
  const [qrCode, setQrCode] = useState(null);
  const [session, setSession] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [countdown, setCountdown] = useState(0);

  // ── Generate QR Code ────────────────────────────
  const generateQR = async (e) => {
    e.preventDefault();
    if (!subject.trim()) return;
    setLoading(true);
    setError('');
    setQrCode(null);
    setSession(null);
    try {
      const res = await API.post('/qr/generate', { subject });
      setQrCode(res.data.qr);
      setSession(res.data.session);
      // Start countdown timer
      const ttl = res.data.session.ttlSeconds;
      setCountdown(ttl);
      const timer = setInterval(() => {
        setCountdown((prev) => {
          if (prev <= 1) { clearInterval(timer); return 0; }
          return prev - 1;
        });
      }, 1000);
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to generate QR');
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => { logout(); navigate('/login'); };

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h1>👨‍🏫 Teacher Dashboard</h1>
        <div>
          <span style={styles.userInfo}>{user?.name}</span>
          <button onClick={handleLogout} style={styles.logoutBtn}>Logout</button>
        </div>
      </div>

      <div style={styles.content}>
        {/* ── QR Generator Form ── */}
        <div style={styles.card}>
          <h2 style={styles.cardTitle}>Generate QR Code</h2>
          <form onSubmit={generateQR} style={styles.form}>
            <input
              value={subject}
              onChange={(e) => setSubject(e.target.value)}
              placeholder="Enter subject name (e.g., Mathematics)"
              style={styles.input}
              required
            />
            <button type="submit" disabled={loading} style={styles.button}>
              {loading ? 'Generating...' : '🎯 Generate QR'}
            </button>
          </form>
          {error && <div style={styles.error}>{error}</div>}
        </div>

        {/* ── QR Code Display ── */}
        {qrCode && session && (
          <div style={styles.card}>
            <h2 style={styles.cardTitle}>📸 Scan this QR</h2>
            <div style={styles.qrContainer}>
              <img src={qrCode} alt="Attendance QR Code" style={styles.qrImage} />
            </div>
            <p style={styles.sessionInfo}>
              <strong>{session.subject}</strong> — Expires in{' '}
              <span style={{ color: countdown < 10 ? '#ff6b6b' : '#6c63ff' }}>
                {countdown}s
              </span>
            </p>
            <p style={{ fontSize: '0.8rem', color: '#888', textAlign: 'center' }}>
              Session: {session.sessionId.slice(0, 16)}...
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

const styles = {
  container: { minHeight: '100vh', padding: '20px' },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '30px',
    flexWrap: 'wrap',
    gap: '10px',
  },
  userInfo: { marginRight: '12px', color: '#a0a0c0' },
  logoutBtn: {
    padding: '8px 16px',
    borderRadius: '6px',
    border: '1px solid rgba(255,255,255,0.2)',
    background: 'transparent',
    color: '#ff6b6b',
    cursor: 'pointer',
  },
  content: { maxWidth: '500px', margin: '0 auto', display: 'flex', flexDirection: 'column', gap: '20px' },
  card: {
    background: 'rgba(255,255,255,0.06)',
    borderRadius: '12px',
    padding: '24px',
    backdropFilter: 'blur(10px)',
  },
  cardTitle: { marginBottom: '16px', fontSize: '1.2rem' },
  form: { display: 'flex', flexDirection: 'column', gap: '12px' },
  input: {
    padding: '10px 14px',
    borderRadius: '8px',
    border: '1px solid rgba(255,255,255,0.15)',
    background: 'rgba(255,255,255,0.06)',
    color: '#fff',
    fontSize: '1rem',
    outline: 'none',
  },
  button: {
    padding: '10px',
    borderRadius: '8px',
    border: 'none',
    background: '#6c63ff',
    color: '#fff',
    fontSize: '1rem',
    fontWeight: 600,
    cursor: 'pointer',
  },
  qrContainer: { display: 'flex', justifyContent: 'center', margin: '16px 0' },
  qrImage: { width: '250px', height: '250px', borderRadius: '8px' },
  sessionInfo: { textAlign: 'center', marginTop: '8px' },
  error: {
    background: 'rgba(255,50,50,0.15)',
    padding: '10px',
    borderRadius: '8px',
    color: '#ff6b6b',
    fontSize: '0.9rem',
    textAlign: 'center',
    marginTop: '12px',
  },
};
